import React from 'react';
import Slider from 'react-slick';
import { Box, Typography, Button } from '@mui/material';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

// Slider İçeriği
const slides = [
  {
    id: 1,
    image: "https://cdn.gcp.techcareer.net/luxoft_hackathon_1112x412_3468c22c84/luxoft_hackathon_1112x412_3468c22c84.png",
    title: "Luxoft Parking Hackathon",
    description: "Yazılım geliştiricileri bu hackathon'da buluşuyor!",
    buttonText: "Detaylı İncele",
    link: "https://www.techcareer.net/hackathon/luxoft-parking-hackathon",
  },
  {
    id: 2,
    image: "https://cdn.gcp.techcareer.net/2024_duyurular_1112x412_ccf8c238f3/2024_duyurular_1112x412_ccf8c238f3.png",
    title: "TechReport 2024 Yazılımcı Anketi",
    description: "Katıl ve yazılım sektörüne katkıda bulun!",
    buttonText: "Ankete Katıl",
    link: "https://survey.alchemer.com/s3/8068418/N240021",
  },
];

const CustomArrow = ({ direction, ...props }) => (
  <Box
    {...props}
    sx={{
      position: 'absolute',
      top: '50%',
      zIndex: 2,
      width: '50px',
      height: '50px',
      backgroundColor: '#fff',
      borderRadius: '50%',
      boxShadow: '0 4px 8px rgba(0, 0, 0, 0.2)',
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      cursor: 'pointer',
      transition: 'all 0.3s ease',
      '&:hover': {
        backgroundColor: '#00C26D',
        color: '#fff',
        transform: 'scale(1.1)',
      },
      [direction === 'prev' ? 'left' : 'right']: '20px',
      transform: 'translateY(-50%)',
    }}
  >
    <Box
      component="span"
      sx={{
        fontSize: '24px',
        fontWeight: 'bold',
        color: '#00C26D',
        '&:hover': {
          color: '#fff',
        },
      }}
    >
      {direction === 'prev' ? '<' : '>'}
    </Box>
  </Box>
);

const TechCareerSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 5000,
    fade: true,
    prevArrow: <CustomArrow direction="prev" />,
    nextArrow: <CustomArrow direction="next" />,
  };

  return (
    <Box sx={{ position: 'relative', overflow: 'hidden', backgroundColor: '#F5F9FF' }}>
      <Slider {...settings}>
        {slides.map((slide) => (
          <Box
            key={slide.id}
            sx={{
              position: 'relative',
              height: { xs: '300px', md: '412px' },
              backgroundImage: `url(${slide.image})`,
              backgroundSize: 'cover',
              backgroundPosition: 'center',
            }}
          >
            {/* Metin ve Buton */}
            <Box
              sx={{
                position: 'absolute',
                bottom: '10%',
                left: '5%',
                color: '#fff',
                zIndex: 2,
                maxWidth: '500px',
              }}
            >
              <Typography variant="h4" sx={{ fontWeight: 'bold', mb: 2 }}>
                {slide.title}
              </Typography>
              <Typography variant="body1" sx={{ mb: 3 }}>
                {slide.description}
              </Typography>
              <Button
                variant="contained"
                href={slide.link}
                sx={{
                  backgroundColor: '#00C26D',
                  '&:hover': {
                    backgroundColor: '#019A57',
                  },
                }}
              >
                {slide.buttonText}
              </Button>
            </Box>
          </Box>
        ))}
      </Slider>
    </Box>
  );
};

export default TechCareerSlider;
